def movement_graph(lines,k,start):
 g=[list(map(int,s)) for s in lines]; H=len(g); W=len(g[0]);
 def mv(p,q):
  r,c=p; rr,cc=q;dr=rr-r;dc=cc-c
  if abs(dr)+abs(dc)!=1 or rr<0 or cc<0 or rr+k>H or cc+k>W:return False
  if dr==1: cells=[(r+k,j) for j in range(c,c+k)]
  elif dr==-1: cells=[(r-1,j) for j in range(c,c+k)]
  elif dc==1: cells=[(i,c+k) for i in range(r,r+k)]
  else: cells=[(i,c-1) for i in range(r,r+k)]
  return all(g[i][j] in (1,2,0) for i,j in cells)
 q=deque([start]); seen={start}; adj={}
 while q:
  p=q.popleft(); adj[p]=[]
  for dr,dc in [(0,1),(0,-1),(1,0),(-1,0)]:
   z=(p[0]+dr,p[1]+dc)
   if mv(p,z):
    adj[p].append(z)
    if z not in seen: seen.add(z);q.append(z)
 return g,seen,adj

