def full_graph(lines,k,start):
 g=[list(map(int,s)) for s in lines]; H=len(g); W=len(g[0])
 def ok(p):
  r,c=p
  return r>=0 and c>=0 and r+k<=H and c+k<=W and all(g[i][j] in (0,1,2) for i in range(r,r+k) for j in range(c,c+k))
 q=deque([start]);seen={start};adj={}
 while q:
  p=q.popleft(); adj[p]=[]
  for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
   z=(p[0]+dr,p[1]+dc)
   if ok(z):
    adj[p].append(z)
    if z not in seen:seen.add(z);q.append(z)
 return seen,adj
